 "content": "from collections import deque


def transform(grid):
    """Copy each nonempty framed pattern into blank frames of matching size."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    frames = []

    # Each monochromatic connected component corresponding to a frame is
    # identified by its bounding box and a complete, solid-color perimeter.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            if (all(grid[r0][x] == color and grid[r1][x] == color
                    for x in range(c0, c1 + 1))
                    and all(grid[y][c0] == color and grid[y][c1] == color
                            for y in range(r0, r1 + 1))):
                frames.append((r0, r1, c0, c1, color))

    # Learn the interior bitmap from any filled frame, grouped by interior size.
    patterns = {}
    for r0, r1, c0, c1, color in frames:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        bitmap = tuple(tuple(grid[y][x] != 0 for x in range(c0 + 1, c1))
                       for y in range(r0 + 1, r1))
        if any(any(row) for row in bitmap):
            patterns.setdefault((ih, iw), bitmap)

    out = [row[:] for row in grid]
    for r0, r1, c0, c1, color in frames:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        bitmap = patterns.get((ih, iw))
        if bitmap is None:
            continue
        # Only fill genuinely blank interiors; existing patterns are preserved.
        if any(grid[y][x] != 0
               for y in range(r0 + 1, r1)
               for x in range(c0 + 1, c1)):
            continue
        for dy in range(ih):
            for dx in range(iw):
                if bitmap[dy][dx]:
                    out[r0 + 1 + dy][c0 + 1 + dx] = color
    return out


if __name__ == '__main__':
    # Small self-check for template copying and recoloring.
    sample = [
        [0, 7, 7, 7, 7],
        [0, 7, 0, 7, 7],
        [0, 7, 7, 7, 7],
        [0, 0, 0, 0, 0],
        [0, 5, 5, 5, 0],
        [0, 5, 0, 5, 0],
        [0, 5, 5, 5, 0],
    ]
    result = transform(sample)
    assert result[5][2] == 5
    print('self-check passed')
